package com.indiesoundquest.tournament.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="music_preference_profile") public class MusicPreferenceProfile {
 @Id private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="guest_session_id",nullable=false) private GuestSession guestSession; @Column(name="profile_json",nullable=false,columnDefinition="json") private String profileJson; @Column(name="use_for_candidate_generation",nullable=false) private boolean useForCandidateGeneration=true; @Column(name="tournament_count",nullable=false) private int tournamentCount; @Column(name="summary_status",nullable=false) private String summaryStatus="STRUCTURED_ONLY"; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt;
 protected MusicPreferenceProfile(){} public static MusicPreferenceProfile create(GuestSession guest,String json,int count){var p=new MusicPreferenceProfile();p.id=UUID.randomUUID();p.guestSession=guest;p.profileJson=json;p.tournamentCount=count;p.createdAt=p.updatedAt=Instant.now();return p;} public void refresh(String json,int count){profileJson=json;tournamentCount=count;summaryStatus="STRUCTURED_ONLY";updatedAt=Instant.now();} public void setUseForCandidateGeneration(boolean value){useForCandidateGeneration=value;updatedAt=Instant.now();} public UUID getId(){return id;} public String getProfileJson(){return profileJson;} public int getTournamentCount(){return tournamentCount;} public boolean isUseForCandidateGeneration(){return useForCandidateGeneration;} public String getSummaryStatus(){return summaryStatus;}
}
